    output = gpgpu.createMatrixTexture(4, 4);
    gpgpu.uploadMatrixToTexture(output, 4, 4, new Float32Array(16));
    gpgpu.setOutputMatrixTexture(output, 4, 4);
    gpgpu.setProgram(program);
  })

