before(function() {
      server = createServer();
      server.on('connection', function(conn) {
        conn.on('error', function() {
          console.log('client drop connection');
        });

        let flags = 0xffffff;
        flags = flags ^ ClientFlags.COMPRESS;

        conn.serverHandshake({
          protocolVersion: 10,
          serverVersion: 'node.js rocks',
          connectionId: 1234,
          statusFlags: 2,
          characterSet: 8,
          capabilityFlags: flags
        });
      });
      server.listen(32883);
    })

