after(async () => {
    const isRunning = await DaemonHandler.isDaemonRunning();
    if (!isRunning) {
      return;
    }
    await new Promise(resolve => {
      DaemonHandler.send('exit', {}, function () {
        resolve();
      });
      setTimeout(resolve, 1000);
    });
  })

