before(() => {
      mm(Messenger, 'getClient', (options) => {
        expect(options.name).equal(SOCKET_FILE_NAME);
        calledGetClient = true;
        return {
          ready: (fn) => {
            if(typeof fn === 'function') {
              fn();
            }
          },
          on: (action, cb) => {
            triggerEvent = cb;
          },
          send: (action, data) => {
            if(data.type === 'logger-heartbeat') {
              if(sendThrowError) {
                throw new Error('mock error');
              }
              heartbeatCount++;
            }
          }
        };
      });
      loggerManager = new OwnLoggerManager({
        connectRotator: true,
        heartbeatTime: 200
      });
    })

before(async () => {
    mm(Messenger, 'getServer', (options) => {
      expect(options.name).equal(SOCKET_FILE_NAME);
      return {
        ready: (cb) => {
          cb && cb();
        },
        on: (action, cb) => {
          triggerEvent = cb;
        },
        broadcast: (action, data) => {
          if(broadcastThrowError) {
            throw new Error('mock error');
          }
          if(data.type === 'logger-reload') {
            broadcastedReload = true;
          }
        }
      };
    });

    loggerRotator = new OwnLoggerRotator({
      heartbeatCheckTime: 300,
      heartbeatTimeMax: 2000
    });
    await loggerRotator.startService();
  })

