beforeEach(function() {
    /* Node.js worker support introduced in version 10.5. */
    if (semver.satisfies(process.versions.node, "< 10.5")) this.skip()
  })

beforeEach(function() {
    /* ZMQ < 4.0.5 has no steerable proxy support. */
    if (semver.satisfies(zmq.version, "< 4.0.5")) this.skip()
  })

beforeEach(async function() {
      /* ZMQ < 4.0.5 has no steerable proxy support. */
      if (semver.satisfies(zmq.version, "< 4.0.5")) this.skip()

      proxy = new zmq.Proxy(new zmq.Router(), new zmq.Dealer())

      frontAddress = uniqAddress(proto)
      backAddress = uniqAddress(proto)

      req = new zmq.Request()
      rep = new zmq.Reply()
    })

afterEach(function() {
      /* Closing proxy sockets is only necessary if run() fails. */
      proxy.frontEnd.close()
      proxy.backEnd.close()

      req.close()
      rep.close()
      global.gc()
    })

beforeEach(async function() {
      /* ZMQ < 4.0.5 has no steerable proxy support. */
      if (semver.satisfies(zmq.version, "< 4.0.5")) this.skip()

      proxy = new zmq.Proxy(new zmq.Router(), new zmq.Dealer())
    })

beforeEach(async function() {
      /* ZMQ < 4.0.5 has no steerable proxy support. */
      if (semver.satisfies(zmq.version, "< 4.0.5")) this.skip()

      proxy = new zmq.Proxy(new zmq.Router(), new zmq.Dealer())
    })

beforeEach(function() {
      if (!zmq.capability.curve) this.skip()

      const serverKeypair = zmq.curveKeyPair()
      const clientKeypair = zmq.curveKeyPair()

      sockA = new zmq.Pair({
        linger: 0,
        curveServer: true,
        curvePublicKey: serverKeypair.publicKey,
        curveSecretKey: serverKeypair.secretKey,
      })

      sockB = new zmq.Pair({
        linger: 0,
        curveServerKey: serverKeypair.publicKey,
        curvePublicKey: clientKeypair.publicKey,
        curveSecretKey: clientKeypair.secretKey,
      })
    })

beforeEach(async function() {
        if (!zmq.capability.curve) this.skip()

        const address = uniqAddress(proto)
        await sockB.bind(address)
        await sockA.connect(address)
      })

